\label{lem:cone}
		Let $\gamma:\mathbb{R}\to\mathbb{C}$ be Lipschitz and suppose that there are $\theta\in \mathbb{R}$, $\Theta\in[0,\pi)$ and $m>0$ such that, almost everywhere,
		\[
		\gamma'(x)\in\mathcal S(\theta,\Theta)\qquad\text{and}\qquad|\gamma'(x)|\ge m .
		\]
		Then:
		\begin{enumerate}[itemsep=0.5em]
			\item[i\,\normalfont{)}] $\gamma$ is injective and $|\gamma(x)-\gamma(y)|\ge m\cos(\Theta/2)\,|x-y|$;
			\item[ii\,\normalfont{)}] $\Gamma=\gamma(\mathbb{R})$ is a rotated Lipschitz graph with constant $\le\tan(\Theta/2)$;
			\item[iii\,\normalfont{)}] for measurable $F\ge0$ on $\Gamma$, $\displaystyle\int_\Gamma F\,d\sigma=\int_\mathbb{R} F(\gamma(x))\,|\gamma'(x)|\,dx$.
		\end{enumerate}

\label{lem:angle}
		Let $\lambda\in\mathbb{C}\setminus[-1,1]$. The vectors $\lambda-1$ and $\lambda+1$ are non-zero and not opposite. Let $\omega(\lambda)\in[0,\pi)$ be the angle between them, that is, the angle under which the segment $[-1,1]$ is seen from $\lambda$. Then:
		\begin{enumerate}[itemsep=0.75em]
			\item[i\,\normalfont{)}] the segment $\{\lambda-a:a\in[-1,1]\}$ is contained in a closed sector of opening $\omega(\lambda)$;
			\item[ii\,\normalfont{)}] $\cos\omega(\lambda)=\dfrac{|\lambda|^2-1}{|\lambda-1||\lambda+1|}$; in particular, $\omega(\lambda)<\pi/2$ if and only if $|\lambda|>1$;
			\item[iii\,\normalfont{)}] $\omega(\bar\lambda)=\omega(-\bar\lambda)=\omega(\lambda)$;
			\item[iv\,\normalfont{)}] if $\operatorname{Im}\lambda\ge0$, then $\omega(\lambda)=\arg(\lambda-1)-\arg(\lambda+1)$, with both arguments in $[0,\pi]$.
		\end{enumerate}

\label{def:contour}
		$\Gamma_\delta$ is the closed curve formed by the following six pieces, traversed in this order:
		\begin{enumerate}[itemsep=0.5em]
			\item right arc $\mathcal A_R$: $\lambda=1+\delta e^{it}$, with $t$ from $-(\pi-\varphi)$ to $\pi-\varphi$;
			\item side $\Sigma_R^+$: $\lambda=1-s+\frac i2 s$, with $s$ from $s_\delta$ to $1$, going from $p_R^+$ to $\frac i2$;
			\item side $\Sigma_L^+$: $\lambda=-1+s+\frac i2 s$, with $s$ from $1$ to $s_\delta$, going from $\frac i2$ to $p_L^+$;
			\item left arc $\mathcal A_L$: $\lambda=-1+\delta e^{it}$, with $t$ from $\varphi$ to $2\pi-\varphi$;
			\item side $\Sigma_L^-$: $\lambda=-1+s-\frac i2 s$, with $s$ from $s_\delta$ to $1$, going from $p_L^-$ to $-\frac i2$;
			\item side $\Sigma_R^-$: $\lambda=1-s-\frac i2 s$, with $s$ from $1$ to $s_\delta$, going from $-\frac i2$ to $p_R^-$;
		\end{enumerate}
		where $p_R^\pm=1-s_\delta\pm\frac i2s_\delta$ and $p_L^\pm=-1+s_\delta\pm\frac i2 s_\delta$.
